// scripts/copy-vendor.mjs — `npm run vendor` (docs/frontend.md §1).
//
// Copies the few files the site uses from node_modules into the repo, where they are committed:
//   - Bootstrap's JS bundle               → static/vendor/bootstrap/
//   - Open Sans (latin, 400/600/700)      → static/vendor/open-sans/
//   - Font Awesome icons, as inline SVGs  → templates/includes/icons/
// Node never reaches an image or a server; the committed copies do.
// Re-run after changing a package version, then run the prod collectstatic (deployment.md §2).

import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

const root = join(dirname(new URL(import.meta.url).pathname), "..");
const nm = (...p) => join(root, "node_modules", ...p);

function copy(from, to) {
  mkdirSync(dirname(to), { recursive: true });
  copyFileSync(from, to);
  console.log(`copied ${to.replace(root + "/", "")}`);
}

// Bootstrap JS (collapse for the mobile navbar, carousel on Day 5).
// Its last line points at a .map file we don't ship. WhiteNoise's manifest storage refuses a
// reference to a missing file and fails collectstatic (the image build), so the line is
// removed here. See docs/errors-and-exceptions/bootstrap-js-sourcemap-breaks-whitenoise-collectstatic__2026-11-03_1105/.
function copyWithoutSourceMap(from, to) {
  mkdirSync(dirname(to), { recursive: true });
  const js = readFileSync(from, "utf8").replace(/\n?\/\/# sourceMappingURL=\S+\s*$/, "\n");
  writeFileSync(to, js);
  console.log(`copied ${to.replace(root + "/", "")} (source-map reference removed)`);
}
copyWithoutSourceMap(
  nm("bootstrap", "dist", "js", "bootstrap.bundle.min.js"),
  join(root, "static", "vendor", "bootstrap", "bootstrap.bundle.min.js"),
);

// Open Sans: the weights and styles _fonts.scss declares.
for (const weight of ["400", "600", "700"]) {
  for (const style of ["normal", "italic"]) {
    const file = `open-sans-latin-${weight}-${style}.woff2`;
    copy(nm("@fontsource", "open-sans", "files", file), join(root, "static", "vendor", "open-sans", file));
  }
}
copy(nm("@fontsource", "open-sans", "LICENSE"), join(root, "static", "vendor", "open-sans", "LICENSE"));

// Font Awesome icons as inline SVG partials: no webfont download, and each icon inherits
// the text colour (fill="currentColor"). Icons are CC BY 4.0 (fontawesome.com/license/free).
const icons = {
  phone: ["solid", "phone"],
  envelope: ["solid", "envelope"],
  "location-dot": ["solid", "location-dot"],
  clock: ["solid", "clock"],
  facebook: ["brands", "facebook-f"],
  linkedin: ["brands", "linkedin-in"],
  instagram: ["brands", "instagram"],
  x: ["brands", "x-twitter"],
};
const iconDir = join(root, "templates", "includes", "icons");
mkdirSync(iconDir, { recursive: true });
for (const [name, [set, file]] of Object.entries(icons)) {
  let svg = readFileSync(nm("@fortawesome", "fontawesome-free", "svgs", set, `${file}.svg`), "utf8");
  svg = svg
    .replace(/<!--[\s\S]*?-->/g, "") // the licence comment is kept once, in README below
    .replace("<svg ", '<svg class="icon" aria-hidden="true" focusable="false" fill="currentColor" ')
    .trim();
  writeFileSync(join(iconDir, `${name}.svg`), svg + "\n");
  console.log(`wrote templates/includes/icons/${name}.svg`);
}
writeFileSync(
  join(iconDir, "README.md"),
  "Generated by `npm run vendor` from @fortawesome/fontawesome-free. Don't edit by hand.\n" +
    "Icons: Font Awesome Free by @fontawesome - https://fontawesome.com, License - " +
    "https://fontawesome.com/license/free (Icons: CC BY 4.0).\n",
);
